public sealed class BillingManager
{
    // invoicing
    private readonly List<string> _issuedNumbers = new();
    private int _nextSeq = 1;
    // tax
    private readonly Dictionary<string, decimal> _vatRates;
    private readonly decimal _reducedRate;
    // dunning
    private readonly Dictionary<string, int> _reminderCounts = new(StringComparer.Ordinal);
    // ledger
    private readonly List<string> _ledger = new();
    private decimal _balance;

    public BillingManager()
    {
        _vatRates = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
        };
        _reducedRate = 0.05m;
    }

    // ---- invoicing ----

    public string CreateInvoice(Invoice invoice, Account account)
    {
        if (string.IsNullOrWhiteSpace(account.Id))
            return "no account";
        if (invoice.Lines.Any(line => string.IsNullOrWhiteSpace(line.Description)))
            return "invalid line";
        if (string.IsNullOrEmpty(invoice.Number))
            invoice.Number = $"INV-{_nextSeq++:D6}";
        if (_issuedNumbers.Contains(invoice.Number))
            return "duplicate";
        if (invoice.Lines.Count == 0)
            return "empty";
        if (account.Kind == AccountKind.Government && string.IsNullOrEmpty(account.BillingAddress))
            return "po required";
        _issuedNumbers.Add(invoice.Number);
        return invoice.Number;
    }

    public bool ValidateInvoice(Invoice invoice)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return false;
        if (invoice.Lines.Count == 0)
            return false;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                return false;
            if (line.VatRate < 0m || line.VatRate > 1m)
                return false;
        }
        return true;
    }

    public int IssuedCount => _issuedNumbers.Count;

    // ---- tax ----

    public decimal ComputeTax(Invoice invoice, string countryCode)
    {
        decimal tax = 0m;
        var rate = ResolveRate(countryCode);
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            if (line.VatRate > 0m)
                tax += line.NetAmount * line.VatRate;
            else if (rate > 0m)
                tax += line.NetAmount * rate;
        }
        return Math.Round(tax, 2);
    }

    public decimal ResolveRate(string countryCode)
    {
        if (string.IsNullOrEmpty(countryCode))
            return _reducedRate;
        if (_vatRates.TryGetValue(countryCode, out var rate))
            return rate;
        return _reducedRate;
    }

    public decimal NetTotal(Invoice invoice)
    {
        decimal net = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                net += line.NetAmount;
        }
        return net;
    }

    // ---- dunning ----

    public string IssueReminder(Invoice invoice, Account account)
    {
        var count = _reminderCounts.TryGetValue(invoice.Number, out var c) ? c : 0;
        if (count >= 3)
            return "escalate";
        if (account.Kind == AccountKind.Government)
            return "no reminder";
        _reminderCounts[invoice.Number] = count + 1;
        if (count == 0)
            return "first notice";
        else if (count == 1)
            return "second notice";
        return "final notice";
    }

    public int ReminderLevel(Invoice invoice)
    {
        if (!_reminderCounts.TryGetValue(invoice.Number, out var c))
            return 0;
        if (c > 3)
            return 3;
        return c;
    }

    // ---- ledger ----

    public void Post(Invoice invoice, decimal amount)
    {
        if (amount == 0m)
            return;
        if (amount > 0m)
            _ledger.Add($"DR {invoice.Number} {amount}");
        else
            _ledger.Add($"CR {invoice.Number} {-amount}");
        _balance += amount;
    }

    public decimal Settle(Invoice invoice, decimal payment)
    {
        if (payment <= 0m)
            return _balance;
        if (string.IsNullOrEmpty(invoice.Number))
            return _balance;
        _ledger.Add($"PMT {invoice.Number} {payment}");
        _balance -= payment;
        if (_balance < 0m)
            _balance = 0m;
        return _balance;
    }

    public decimal ApplyLateFees(Invoice invoice, Account account)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return 0m;
        var level = _reminderCounts.TryGetValue(invoice.Number, out var c) ? c : 0;
        if (level <= 0)
            return 0m;
        if (account.Kind == AccountKind.Government)
            return 0m;
        decimal fee = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            fee += line.NetAmount * 0.01m * level;
        }
        if (account.Kind == AccountKind.Business && fee > 100m)
            fee = 100m;
        else if (fee > 50m)
            fee = 50m;
        return Math.Round(fee, 2);
    }

    public string Reconcile(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "no account";
        if (_ledger.Count == 0)
            return "no entries";
        decimal credits = 0m, debits = 0m;
        foreach (var entry in _ledger)
        {
            if (entry.StartsWith("CR", StringComparison.Ordinal))
                credits += 1m;
            else if (entry.StartsWith("DR", StringComparison.Ordinal))
                debits += 1m;
            else if (entry.StartsWith("PMT", StringComparison.Ordinal))
                credits += 1m;
        }
        if (_balance > 0m && debits > credits)
            return "outstanding";
        if (_balance <= 0m)
            return "settled";
        return "partial";
    }

    public decimal Balance => _balance;
}

